import{_ as l,a0 as p,w as d,s as o,ao as r,I as n,x as a,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 中创建 LVM 分区的分步指南 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中创建 LVM 分区的分步指南 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中创建 LVM 分区的分步指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中创建 LVM 分区的分步指南 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221008 How to Create LVM Partition Step-by-Step in Linux","title":"在 Linux 中创建 LVM 分区的分步指南","tag":"202210","desc":""},"relativePath":"202210/20221008 How to Create LVM Partition Step-by-Step in Linux.md","filePath":"[post].md"}'),h={name:"202210/20221008 How to Create LVM Partition Step-by-Step in Linux.md"};function c(g,s,u,k,b,m){const i=p("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="在-linux-中创建-lvm-分区的分步指南" tabindex="-1">在 Linux 中创建 LVM 分区的分步指南 <a class="header-anchor" href="#在-linux-中创建-lvm-分区的分步指南" aria-label="Permalink to “在 Linux 中创建 LVM 分区的分步指南”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/18/113615swffwazya3nyfve2.jpg" alt=""></p><blockquote><p>在本指南中，我们将逐步介绍如何在 Linux 中创建 LVM 分区。</p></blockquote><p>LVM 代表 “<ruby>逻辑卷管理<rt>Logical Volume Management</rt></ruby>”，它是专门为服务器管理 Linux 系统上的磁盘或存储的推荐方式。 LVM 分区的主要优点之一是我们可以实时扩展其大小而无需停机。 LVM 分区也可以缩小，但不推荐。</p><p>为了演示，我在我的 Ubuntu 22.04 系统上连接了 15GB 磁盘，我们将从命令行在该磁盘上创建 LVM 分区。</p><h5 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to “准备”">​</a></h5><ul><li>连接到 Linux 系统的原始磁盘</li><li>具有 sudo 权限的本地用户</li><li>预装 lvm2 包</li></ul><p>事不宜迟，让我们深入了解这些步骤。</p><h3 id="步骤-1、识别新连接的原始磁盘" tabindex="-1">步骤 1、识别新连接的原始磁盘 <a class="header-anchor" href="#步骤-1、识别新连接的原始磁盘" aria-label="Permalink to “步骤 1、识别新连接的原始磁盘”">​</a></h3><p>登录到你的系统，打开终端并运行以下 <code>dmesg</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dmesg | grep -i sd</span></span></code></pre></div><p>在输出中，查找大小为 15GB 的新磁盘。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/dmesg-command-new-attached-disk-linux.png" alt="dmesg-command-new-attached-disk-linux"></p><p>识别新连接的原始磁盘的另一种方法是通过 <code>fdisk</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo fdisk -l | grep -i /dev/sd</span></span></code></pre></div><p>输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/fdisk-command-output-new-disk.png" alt="fdisk-command-output-new-disk"></p><p>从上面的输出，可以确认新连接的磁盘是 <code>/dev/sdb</code>。</p><h3 id="步骤-2、创建-pv-物理卷" tabindex="-1">步骤 2、创建 PV（物理卷） <a class="header-anchor" href="#步骤-2、创建-pv-物理卷" aria-label="Permalink to “步骤 2、创建 PV（物理卷）”">​</a></h3><p>在开始在磁盘 <code>/dev/sdb</code> 上创建<ruby>物理卷<rt>Physical Volume</rt></ruby>（PV）之前，请确保已安装 <code>lvm2</code> 包。如果未安装，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install lvm2     // On Ubuntu / Debian</span></span>
<span class="line"><span>$ sudo dnf install lvm2    // on RHEL / CentOS</span></span></code></pre></div><p>运行以下 <code>pvcreate</code> 命令在磁盘 <code>/dev/sdb</code> 上创建 PV：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pvcreate /dev/sdb</span></span>
<span class="line"><span>  Physical volume &quot;/dev/sdb&quot; successfully created.</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>要验证 PV 状态，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pvs /dev/sdb</span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span>$ sudo pvdisplay /dev/sdb</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/pvdisplay-command-output-linux.png" alt="pvdisplay-command-output-linux"></p><h3 id="步骤-3、创建-vg-卷组" tabindex="-1">步骤 3、创建 VG（卷组） <a class="header-anchor" href="#步骤-3、创建-vg-卷组" aria-label="Permalink to “步骤 3、创建 VG（卷组）”">​</a></h3><p>要创建<ruby>卷组<rt>Volume Group</rt></ruby>（VG），我们将使用 <code>vgcreate</code> 命令。创建 VG 意味着将 PV 添加到其中。</p><p>语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgcreare &lt;vg_name&gt;  &lt;pv&gt;</span></span></code></pre></div><p>在我们的例子中，命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgcreate volgrp01 /dev/sdb</span></span>
<span class="line"><span>  Volume group &quot;volgrp01&quot; successfully created</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>运行以下命令以验证 VG（<code>volgrp01</code>）的状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgs volgrp01</span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span>$ sudo vgdisplay volgrp01</span></span></code></pre></div><p>上述命令的输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/vgs-command-output-linux.png" alt="vgs-command-output-linux"></p><p>以上输出确认大小为 15 GiB 的卷组 <code>volgrp01</code> 已成功创建，一个<ruby>物理扩展<rt>Physical Extend</rt></ruby>（PE）的大小为 4 MB。创建 VG 时可以更改 PE 大小。</p><h3 id="步骤-4、创建-lv-逻辑卷" tabindex="-1">步骤 4、创建 LV（逻辑卷） <a class="header-anchor" href="#步骤-4、创建-lv-逻辑卷" aria-label="Permalink to “步骤 4、创建 LV（逻辑卷）”">​</a></h3><p><code>lvcreate</code> 命令用于从 VG 中创建<ruby>逻辑卷<rt>Logical Volume</rt></ruby> LV。 <code>lvcreate</code> 命令的语法如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvcreate -L &lt;Size-of-LV&gt; -n &lt;LV-Name&gt;   &lt;VG-Name&gt;</span></span></code></pre></div><p>在我们的例子中，以下命令将用于创建大小为 14 GB 的 LV：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvcreate -L 14G -n lv01 volgrp01</span></span>
<span class="line"><span>  Logical volume &quot;lv01&quot; created.</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>验证 LV 的状态，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvs /dev/volgrp01/lv01</span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span>$ sudo lvdisplay /dev/volgrp01/lv01</span></span></code></pre></div><p>输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/lvs-command-output-linux.png" alt="lvs-command-output-linux"></p><p>上面的输出显示 LV（<code>lv01</code>）已成功创建，大小为 14 GiB。</p><h3 id="步骤-5、格式化-lvm-分区" tabindex="-1">步骤 5、格式化 LVM 分区 <a class="header-anchor" href="#步骤-5、格式化-lvm-分区" aria-label="Permalink to “步骤 5、格式化 LVM 分区”">​</a></h3><p>使用 <code>mkfs</code> 命令格式化 LVM 分区。在我们的例子中，LVM 分区是 <code>/dev/volgrp01/lv01</code>。</p><p>注意：我们可以将分区格式化为 ext4 或 xfs，因此请根据你的设置和要求选择文件系统类型。</p><p>运行以下命令将 LVM 分区格式化为 ext4 文件系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkfs.ext4 /dev/volgrp01/lv01</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/mkfs-ext4-filesystem-lvm.png" alt="mkfs-ext4-filesystem-lvm"></p><p>执行下面的命令，用 xfs 文件系统格式化 LVM 分区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkfs.xfs /dev/volgrp01/lv01</span></span></code></pre></div><p>要使用上述格式化分区，我们必须将其挂载到某个文件夹中。所以，让我们创建一个文件夹 <code>/mnt/data</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /mnt/data</span></span></code></pre></div><p>现在运行 <code>mount</code> 命令将其挂载到 <code>/mnt/data</code> 文件夹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mount /dev/volgrp01/lv01 /mnt/data/</span></span>
<span class="line"><span>$ df -Th /mnt/data/</span></span>
<span class="line"><span>Filesystem                Type  Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/mapper/volgrp01-lv01 ext4   14G   24K   13G   1% /mnt/data</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>尝试创建一些没用的文件，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /mnt/data/</span></span>
<span class="line"><span>$ echo &quot;testing lvm partition&quot; | sudo tee dummy.txt</span></span>
<span class="line"><span>$ cat dummy.txt</span></span>
<span class="line"><span>testing lvm partition</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ sudo rm -f  dummy.txt</span></span></code></pre></div><p>完美，以上命令输出确认我们可以访问 LVM 分区。</p><p>要永久挂载上述 LVM 分区，请使用以下 <code>echo</code> 命令将其条目添加到 <code>fstab</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;/dev/volgrp01/lv01  /mnt/data  ext4  defaults 0 0&#39; | sudo  tee -a /etc/fstab</span></span>
<span class="line"><span>$ sudo mount -a</span></span></code></pre></div><p>以上就是本指南的全部内容，感谢阅读。请在下面的评论区发表你的问题和反馈。</p><hr>`,66)),n("p",null,[s[1]||(s[1]=a("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/how-to-create-lvm-partition-in-linux/"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/how-to-create-lvm-partition-in-linux/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=a("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/james/"},{default:t(()=>[...s[2]||(s[2]=[a("James Kiarie",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(i,{href:"https://github.com/lkxed"},{default:t(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux 中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const y=l(h,[["render",c]]);export{x as __pageData,y as default};
